import hashlib, json, re, sys; open(sys.argv[1], "w").write(json.dumps({"schema_version": 1, "max_ngram": 4, "purpose": "sha256 digests of lower-cased word n-grams that no tracked text file may contain (tests/unit/test_repo_hygiene.py). Regenerate with: python scripts/maintenance/hygiene_denylist.py OUT PHRASE...", "digests": sorted({hashlib.sha256(" ".join(re.findall(r"[a-z0-9]+", p.lower())).encode()).hexdigest() for p in sys.argv[2:]})}, indent=2) + "\n")
